// A supplier attaches two invoices and a signature image to the same email,
// and n8n hands all three over on one item as attachment_0, attachment_1,
// attachment_2. A workflow that reads attachment_0 and moves on loses the
// second invoice and never says so.
//
// The emails are pulled from the trigger by name rather than from this node's
// input, because the three register reads sit in between and they replaced
// what was on the wire.

let emails = [];
try {
  emails = $('When Invoice Email Arrives').all();
} catch (e) {
  emails = $input.all();            // esecuzione a mano, senza la posta
}

const out = [];

for (const email of emails) {
  const files = email.binary || {};
  const meta = email.json || {};

  for (const key of Object.keys(files)) {
    const file = files[key];
    const name = String(file.fileName || '').toLowerCase();
    const type = String(file.mimeType || '').toLowerCase();
    if (!type.includes('pdf') && !name.endsWith('.pdf')) continue;

    out.push({
      json: {
        source_file: file.fileName || key,
        sender: meta.from || '',
        subject: meta.subject || '',
        message_id: meta.id || '',
        received_at: meta.date || new Date().toISOString(),
      },
      binary: { invoice: file },
    });
  }
}

// Nessun PDF non e' un guasto: e' un'email qualunque. Zero elementi fermano
// il ramo senza scrivere niente nel registro.
return out;

// Everything that can be settled from the invoice alone, before any register
// is opened. Two jobs: put the numbers and the dates into one shape, and ask
// the invoice whether it agrees with itself.

const cfg = $('Set Workflow Parameters').first().json;
const src = $('Loop Over Invoices').first().json;
const raw = $json.output || $json;        // l'estrattore incapsula, non sempre

const pad = (v) => String(v).padStart(2, '0');

// 1.234,56 e 1,234.56 sono lo stesso importo scritto da due continenti. Il
// separatore decimale e' l'ultimo dei due che compare; una virgola sola e'
// decimale se ha una o due cifre dopo, migliaia altrimenti.
function money(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  let s = String(value == null ? '' : value).trim();
  if (!s) return null;
  const negative = /^\(.*\)$/.test(s) || s.trim().startsWith('-');
  s = s.replace(/[()]/g, '').replace(/[^0-9.,]/g, '');
  if (!s) return null;
  const comma = s.lastIndexOf(',');
  const dot = s.lastIndexOf('.');
  if (comma > -1 && dot > -1) {
    s = comma > dot ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (comma > -1) {
    s = /,\d{1,2}$/.test(s) ? s.replace(',', '.') : s.replace(/,/g, '');
  }
  const n = Number(s);
  if (!Number.isFinite(n)) return null;
  return negative ? -n : n;
}

// 03/04/2026 e' il 3 aprile quasi ovunque e il 4 marzo negli Stati Uniti.
// Quando uno dei due numeri e' maggiore di 12 la questione si chiude da sola;
// quando non lo e', decide date_order nelle impostazioni. Una scadenza letta
// al contrario e' un pagamento in ritardo di un mese.
function isoDate(value) {
  const s = String(value == null ? '' : value).trim();
  if (!s) return '';
  let m = s.match(/^(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})$/);
  if (m) return `${m[1]}-${pad(m[2])}-${pad(m[3])}`;
  m = s.match(/^(\d{1,2})[-/.](\d{1,2})[-/.](\d{4})$/);
  if (m) {
    const a = Number(m[1]);
    const b = Number(m[2]);
    const dayFirst = a > 12 ? true : b > 12 ? false : String(cfg.date_order) !== 'MDY';
    return `${m[3]}-${pad(dayFirst ? b : a)}-${pad(dayFirst ? a : b)}`;
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? '' : d.toISOString().slice(0, 10);
}

// Il resto 97, la regola ISO 13616: si sposta il codice paese in fondo, si
// sostituisce ogni lettera con la sua posizione piu' 9, e il resto della
// divisione per 97 deve fare 1. Un IBAN con una cifra sbagliata non passa.
function ibanValid(value) {
  const s = String(value || '').replace(/[\s-]/g, '').toUpperCase();
  if (!/^[A-Z]{2}[0-9]{2}[A-Z0-9]{10,30}$/.test(s)) return false;
  const LENGTH = { AT: 20, BE: 16, CH: 21, CZ: 24, DE: 22, DK: 18, EE: 20, ES: 24,
                   FI: 18, FR: 27, GB: 22, GR: 27, HR: 21, HU: 28, IE: 22, IT: 27,
                   LT: 20, LU: 20, LV: 21, NL: 18, NO: 15, PL: 28, PT: 25, RO: 24,
                   SE: 24, SI: 19, SK: 24 };
  const expected = LENGTH[s.slice(0, 2)];
  if (expected && s.length !== expected) return false;
  let remainder = 0;
  for (const ch of s.slice(4) + s.slice(0, 4)) {
    const digits = ch >= 'A' && ch <= 'Z' ? String(ch.charCodeAt(0) - 55) : ch;
    for (const d of digits) remainder = (remainder * 10 + Number(d)) % 97;
  }
  return remainder === 1;
}

// "ACME Ltd.", "Acme Limited" e "acme" sono lo stesso fornitore. Si toglie la
// forma giuridica, la punteggiatura e gli accenti, e resta il nome.
const LEGAL = /\b(ltd|limited|llc|inc|incorporated|corp|corporation|co|company|gmbh|ag|bv|nv|sa|sas|sarl|srl|spa|oy|ab|as|aps|plc|pty|kg|ug|sl|kft|doo)\b/g;
function supplierKey(name) {
  return String(name || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(LEGAL, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const supplier = String(raw.supplier_name || '').trim();
const number = String(raw.invoice_number || '').trim();
const net = money(raw.net_amount);
const tax = money(raw.tax_amount);
const total = money(raw.total_amount);
const invoiceDate = isoDate(raw.invoice_date);
const dueDate = isoDate(raw.due_date);
const iban = String(raw.iban || '').replace(/[\s-]/g, '').toUpperCase();

const problems = [];
if (!supplier) problems.push('no supplier name on the invoice');
if (!number) problems.push('no invoice number on the invoice');
if (total === null) problems.push('no total that could be read as a number');
if (!invoiceDate) problems.push('no invoice date that could be read as a date');

// Un totale che non e' la somma delle sue parti: o l'estrazione ha sbagliato
// a leggere, o la fattura e' sbagliata. In nessuno dei due casi si paga.
const rounding = Number(cfg.rounding_tolerance) || 0.02;
let arithmetic = 'not checked';
if (net !== null && tax !== null && total !== null && (net !== 0 || tax !== 0)) {
  const drift = Math.abs(net + tax - total);
  arithmetic = drift <= rounding ? 'ok' : `out by ${drift.toFixed(2)}`;
  if (drift > rounding) {
    problems.push(`net + tax comes to ${(net + tax).toFixed(2)}, the total says ${total.toFixed(2)}`);
  }
}

// L'aliquota implicita non si giudica, si mostra. Sopra il 30% e' quasi
// sempre un numero letto male, non un'imposta che esiste.
let vatRate = null;
if (net) {
  vatRate = Math.round((tax === null ? 0 : tax) / net * 1000) / 10;
  if (vatRate < 0 || vatRate > 30) {
    problems.push(`the implied VAT rate is ${vatRate}%, which is not a rate anybody charges`);
  }
}

if (invoiceDate && dueDate && dueDate < invoiceDate) {
  problems.push('the due date falls before the invoice date');
}

const ibanOk = iban ? ibanValid(iban) : null;
if (iban && !ibanOk) problems.push('the IBAN on the invoice fails its check digits');

const key = supplierKey(supplier);
const currency = String(raw.currency || cfg.default_currency || '').toUpperCase().slice(0, 3);

return [{
  json: {
    ...src,
    supplier_name: supplier,
    supplier_key: key,
    invoice_number: number,
    invoice_number_key: number.toLowerCase().replace(/[^a-z0-9]/g, ''),
    invoice_key: `${key}|${number.toLowerCase().replace(/[^a-z0-9]/g, '')}`,
    invoice_date: invoiceDate,
    due_date: dueDate,
    po_number: String(raw.po_number || '').trim(),
    po_number_key: String(raw.po_number || '').toLowerCase().replace(/[^a-z0-9]/g, ''),
    currency,
    net_amount: net,
    tax_amount: tax,
    total_amount: total,
    implied_vat_rate: vatRate,
    arithmetic,
    iban,
    iban_valid: ibanOk,
    readable: Boolean(supplier && number && total !== null),
    problems,
  },
}];

// Three questions, in the order of what they cost when nobody asks them.
//
//   1. Have we already paid this? A duplicate payment is money gone, and the
//      one that gets paid twice is rarely the same number twice: it is the
//      same supplier and the same amount, weeks later, under a new number.
//   2. Is the money going where it went last time? Changing the bank details
//      on an otherwise genuine invoice is the whole of invoice fraud.
//   3. Was it ordered, was this much ordered, and did it arrive? Invoice
//      against purchase order against goods received: the three-way match.
//
// Nothing here decides anything on its own. Each check appends to one `risk`
// list with a severity, and the decision at the bottom reads that list. Add a
// check of your own the same way and the routing, the emails and the ledger
// pick it up without another edit.

const cfg = $('Set Workflow Parameters').first().json;
const inv = $json;

// Google Sheets returns a blank item for an empty tab; drop those.
const clean = (bag) => (bag || []).filter((r) => r && Object.keys(r).length);
const suppliers = clean($('Aggregate Supplier Data').first().json.rows);
const orders = clean($('Aggregate Purchase Orders').first().json.rows);
const ledger = clean($('Aggregate Ledger Data').first().json.rows);

// Le stesse normalizzazioni del nodo precedente. Ripetute perche' due nodi
// Code non condividono lo scope: sono dieci righe, e vale il prezzo.
const LEGAL = /\b(ltd|limited|llc|inc|incorporated|corp|corporation|co|company|gmbh|ag|bv|nv|sa|sas|sarl|srl|spa|oy|ab|as|aps|plc|pty|kg|ug|sl|kft|doo)\b/g;
const key = (name) => String(name || '').toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/&/g, ' and ').replace(/[^a-z0-9 ]/g, ' ')
  .replace(LEGAL, ' ').replace(/\s+/g, ' ').trim();
const flat = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const num = (v) => {
  const n = Number(String(v == null ? '' : v).replace(/[^0-9.-]/g, ''));
  return Number.isFinite(n) ? n : 0;
};
const cash = (v) => `${inv.currency || ''} ${Number(v || 0).toFixed(2)}`.trim();

// Distanza di Levenshtein, una riga per volta invece che tutta la matrice.
function editDistance(a, b) {
  if (a === b) return 0;
  if (!a.length || !b.length) return Math.max(a.length, b.length);
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) {
      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1,
                        prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[b.length];
}

// Tre misure, e vince la piu' generosa. La distanza prende i refusi lunghi;
// le parole in comune prendono i nomi accorciati ("Acme" per "Acme
// Industries"), dove la distanza direbbe di no; e una o due lettere di
// differenza contano come lo stesso nome a prescindere dalla lunghezza,
// perche' su un nome corto un refuso solo pesa troppo: "aceme" contro "acme"
// fa 0,80, sotto qualunque soglia ragionevole, e sono la stessa ditta.
function similarity(a, b) {
  if (!a || !b) return 0;
  const gap = editDistance(a, b);
  const byEdit = 1 - gap / Math.max(a.length, b.length);
  const ta = new Set(a.split(' ').filter(Boolean));
  const tb = new Set(b.split(' ').filter(Boolean));
  const shared = [...ta].filter((t) => tb.has(t)).length;
  const byToken = shared / Math.max(ta.size, tb.size, 1);
  const byTypo = gap <= (Math.max(a.length, b.length) > 12 ? 2 : 1) ? 0.9 : 0;
  return Math.max(byEdit, byToken, byTypo);
}

// Confrontati due volte: senza la forma giuridica, che e' cio' che distingue
// due ditte, e con tutto attaccato, che e' cio' che salva il caso in cui il
// refuso e' nella forma giuridica stessa ("Acme Limted"), dove togliere la
// parola non la toglie e il nome resta piu' lungo dell'altro.
const alike = (a, b) => Math.max(similarity(key(a), key(b)), similarity(flat(a), flat(b)));

const risk = [];
const add = (severity, code, detail) => risk.push({ severity, code, detail });

// --- 1. l'abbiamo gia' pagata? --------------------------------------------
const DAY = 86400000;
const window = Number(cfg.duplicate_window_days) || 60;
const issued = inv.invoice_date ? Date.parse(inv.invoice_date) : Date.now();

const sameNumber = ledger.filter((r) =>
  flat(r.invoice_number) &&
  flat(r.invoice_number) === inv.invoice_number_key &&
  key(r.supplier_name) === inv.supplier_key);

const sameAmount = ledger.filter((r) => {
  if (key(r.supplier_name) !== inv.supplier_key) return false;
  if (flat(r.invoice_number) === inv.invoice_number_key) return false;
  if (Math.abs(num(r.total_amount) - (inv.total_amount || 0)) > 0.01) return false;
  const when = Date.parse(r.invoice_date);
  return !Number.isNaN(when) && Math.abs(issued - when) <= window * DAY;
});

if (sameNumber.length) {
  const first = sameNumber[0];
  add('block', 'duplicate',
    `invoice ${inv.invoice_number} from ${inv.supplier_name} is already in the ledger, ` +
    `recorded ${first.recorded_on || 'earlier'} as ${first.decision || 'processed'}`);
}

if (sameAmount.length) {
  const first = sameAmount[0];
  const apart = Math.round(Math.abs(issued - Date.parse(first.invoice_date)) / DAY);
  add('block', 'near-duplicate',
    `${cash(inv.total_amount)} from ${inv.supplier_name} was already billed ${apart} day(s) ago ` +
    `under number ${first.invoice_number}. Same supplier, same amount, different number: ` +
    `this is the shape a double payment actually arrives in`);
}

// --- 2. il conto e' quello di sempre? -------------------------------------
const threshold = Number(cfg.supplier_match_threshold) || 0.82;
const nameOf = (r) => r.supplier_name || r.name || '';

let supplierRow = suppliers.find((r) => key(nameOf(r)) === inv.supplier_key) || null;
let score = supplierRow ? 1 : 0;

if (!supplierRow) {
  for (const r of suppliers) {
    const s = alike(inv.supplier_name, nameOf(r));
    if (s > score) { score = s; if (s >= threshold) supplierRow = r; }
  }
  if (supplierRow) {
    add('note', 'supplier-matched-loosely',
      `"${inv.supplier_name}" matched to "${nameOf(supplierRow)}" on the master file ` +
      `(${Math.round(score * 100)}% alike)`);
  }
}

if (!supplierRow) {
  add('block', 'unknown-supplier',
    `"${inv.supplier_name}" is not on the supplier master file` +
    (score > 0.5 ? `; the closest name there is only ${Math.round(score * 100)}% alike` : ''));
}

const onFile = String((supplierRow && (supplierRow.iban || supplierRow.bank_account)) || '')
  .replace(/[\s-]/g, '').toUpperCase();

if (onFile && inv.iban && onFile !== inv.iban) {
  add('block', 'bank-details-changed',
    `this invoice asks to be paid to an account ending ${inv.iban.slice(-4)}; ` +
    `the account on file for ${nameOf(supplierRow)} ends ${onFile.slice(-4)}. ` +
    `Confirm the change by phone, on a number you already had — never on one ` +
    `printed on the invoice, and never by replying to the email`);
}

if (inv.iban && inv.iban_valid === false) {
  add('block', 'iban-invalid', 'the IBAN on the invoice fails its check digits');
}

if (!inv.iban && !onFile) {
  add('review', 'no-bank-details', 'no IBAN on the invoice and none on file for this supplier');
}

// --- 3. era stata ordinata, e per questo importo? -------------------------
const tolerance = Number(cfg.amount_tolerance_pct) || 2;
let po = null;
let matchedBy = 'nothing';

if (inv.po_number_key) {
  po = orders.find((r) => flat(r.po_number) === inv.po_number_key) || null;
  if (po) matchedBy = `the PO number quoted on the invoice (${po.po_number})`;
  else {
    add('review', 'po-not-found',
      `the invoice quotes purchase order ${inv.po_number}, which is not in the register`);
  }
}

if (!po && supplierRow) {
  // Nessun numero d'ordine: si prova per fornitore e importo, e lo si dichiara.
  // Un abbinamento trovato cosi' non e' una prova, e' un indizio.
  const open = orders.filter((r) =>
    key(r.supplier_name) === key(nameOf(supplierRow)) &&
    String(r.status || '').toLowerCase() !== 'closed');
  po = open.find((r) =>
    Math.abs(num(r.amount) - (inv.total_amount || 0)) <= Math.abs(num(r.amount)) * tolerance / 100) || null;
  if (po) {
    matchedBy = `supplier and amount, with no PO number on the invoice`;
    add('review', 'po-matched-loosely',
      `no purchase order quoted; matched to ${po.po_number} because the supplier and the ` +
      `amount line up. Worth one human glance before it is paid`);
  }
}

let variance = null;
if (po) {
  const ordered = num(po.amount);
  const allowed = Math.abs(ordered) * tolerance / 100;
  const receivedRaw = po.received_amount;
  const received = receivedRaw === undefined || receivedRaw === null || receivedRaw === ''
    ? null : num(receivedRaw);
  variance = (inv.total_amount || 0) - ordered;

  if (variance > allowed) {
    add('block', 'over-the-order',
      `billed ${cash(inv.total_amount)} against a purchase order of ${cash(ordered)} — ` +
      `${cash(variance)} over, and ${tolerance}% is what you allow`);
  } else if (-variance > allowed) {
    add('note', 'under-the-order',
      `billed ${cash(Math.abs(variance))} under ${po.po_number}, which usually means a ` +
      `part delivery. Worth knowing before the order is closed`);
  }

  if (received === null) {
    add('review', 'nothing-received',
      `nothing is recorded as received against ${po.po_number}. This is a two-way match, ` +
      `not a three-way one: the goods may not have arrived`);
  } else if (received + 0.01 < (inv.total_amount || 0)) {
    add('block', 'billed-more-than-received',
      `${cash(received)} recorded as received against ${po.po_number}, ` +
      `${cash(inv.total_amount)} billed`);
  }

  if (String(po.status || '').toLowerCase() === 'closed') {
    add('review', 'order-closed', `${po.po_number} is already marked closed`);
  }
} else if (!inv.po_number_key) {
  add('review', 'no-order',
    'no purchase order quoted on the invoice, and no open order for this supplier matches the amount');
}

// Quello che la fattura non ha superato da sola entra nella stessa lista.
for (const p of inv.problems || []) add('review', 'invoice-self-check', p);

// --- la decisione ---------------------------------------------------------
const blockers = risk.filter((r) => r.severity === 'block');
const reviews = risk.filter((r) => r.severity === 'review');
const autoLimit = Number(cfg.auto_approve_limit) || 0;
const managerLimit = Number(cfg.manager_limit) || 0;
const total = inv.total_amount || 0;

let decision;
let approver = '';
if (!inv.readable) {
  decision = 'unreadable';
} else if (blockers.length) {
  decision = 'blocked';
} else if (!reviews.length && po && total <= autoLimit) {
  decision = 'cleared';
} else {
  decision = 'approval';
  approver = total <= managerLimit ? cfg.ap_manager_email : cfg.finance_email;
}

const line = (label, value) => `${(label + ':').padEnd(18)}${value}`;
const summary = [
  line('Supplier', inv.supplier_name || '(not read)'),
  line('Invoice', inv.invoice_number || '(not read)'),
  line('Dated', inv.invoice_date || '(not read)'),
  line('Due', inv.due_date || '(not stated)'),
  line('Total', cash(total)),
  line('Net / tax', `${cash(inv.net_amount)} / ${cash(inv.tax_amount)}` +
    (inv.implied_vat_rate === null ? '' : ` (${inv.implied_vat_rate}%)`)),
  line('Adds up', inv.arithmetic),
  line('Paid to', inv.iban ? `${inv.iban} (${inv.iban_valid ? 'valid' : 'FAILS CHECKSUM'})` : '(not stated)'),
  line('Matched to', po ? `${po.po_number} by ${matchedBy}` : 'no purchase order'),
  line('Attachment', inv.source_file || ''),
  line('From', inv.sender || ''),
].join('\n');

const findings = risk.length
  ? risk.map((r) => `  [${r.severity.toUpperCase()}] ${r.detail}`).join('\n')
  : '  Nothing. Every check passed.';

return [{
  json: {
    ...inv,
    decision,
    approver_email: approver,
    po_number_matched: po ? po.po_number : '',
    po_amount: po ? num(po.amount) : null,
    po_variance: variance,
    matched_by: matchedBy,
    supplier_on_file: supplierRow ? nameOf(supplierRow) : '',
    supplier_match_score: Math.round(score * 100) / 100,
    risk,
    risk_codes: risk.map((r) => r.code).join(', '),
    blocker_count: blockers.length,
    review_count: reviews.length,
    summary,
    findings,
  },
}];

parameters.message:
=This invoice was not passed for approval. It is held.

{{ $json.summary }}

WHY IT IS HELD
{{ $json.findings }}

Nothing is paid and nobody has been asked to approve it. Resolve it, then set the row's status to 'resolved' in the Ledger tab — the morning sweep lists it every day until you do.

=This invoice passed the automatic checks but is not small enough, or not clean enough, to go through on its own.

{{ $json.summary }}

WHAT THE CHECKS FOUND
{{ $json.findings }}

Approving records it as approved for payment. Declining records it as rejected. Either way it is written to the ledger with your name against it.

=An invoice arrived that could not be read well enough to check.

{{ $json.summary }}

WHAT WAS MISSING
{{ $json.findings }}

The file is attached to the original email: "{{ $json.subject }}", from {{ $json.sender }}. It has been recorded in the ledger as unreadable so it cannot quietly disappear.

