// The morning pass over the ledger. It does not repeat the checks above — it
// looks at what they left open, which is the part a checklist never covers.
//
// I due numeri che vale la pena cambiare stanno qui sopra a tutto, perche'
// questo ramo parte da un trigger suo e non vede Set Workflow Parameters.
const CHASE_AFTER_DAYS = 2;     // da quanti giorni un'approvazione senza risposta e' un problema
const DUE_WITHIN_DAYS = 3;      // con quanto anticipo avvisare di una scadenza

const rows = $input.all().map((i) => i.json).filter((r) => r && r.invoice_number);

const today = new Date();
today.setHours(0, 0, 0, 0);

// Date.parse('2026-02-03') e' mezzanotte UTC, e today e' mezzanotte locale:
// sottrarre l'una dall'altra sposta il conto di un giorno intero appena il
// fuso non e' Greenwich. Le date del registro sono giorni di calendario, non
// istanti, e vanno lette come tali.
const atMidnight = (value) => {
  const m = String(value || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  return m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])).getTime() : NaN;
};
const daysSince = (value) => {
  const t = atMidnight(value);
  return Number.isNaN(t) ? null : Math.round((today.getTime() - t) / 86400000);
};

const key = (name) => String(name || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const settled = ['paid', 'rejected', 'cancelled', 'resolved'];

const waiting = [];
const dueSoon = [];
const held = [];
const doubled = [];
const byFingerprint = new Map();

for (const r of rows) {
  const decision = String(r.decision || '').toLowerCase();
  const status = String(r.status || '').toLowerCase();
  const open = !settled.includes(status);
  const age = daysSince(r.recorded_on);
  const amount = `${r.currency || ''} ${r.total_amount || ''}`.trim();

  if (open && decision === 'approval' && age !== null && age >= CHASE_AFTER_DAYS) {
    waiting.push(`  ${r.supplier_name} ${r.invoice_number} - ${amount} - with ` +
                 `${r.approver || 'an approver'} for ${age} day(s)`);
  }

  if (open && decision === 'blocked') {
    held.push(`  ${r.supplier_name} ${r.invoice_number} - ${amount} - held: ${r.risk || 'see the ledger'}`);
  }

  if (open && r.due_date) {
    const left = -daysSince(r.due_date);
    if (left !== null && left <= DUE_WITHIN_DAYS) {
      dueSoon.push(`  ${r.supplier_name} ${r.invoice_number} - ${amount} - ` +
                   (left < 0 ? `overdue by ${-left} day(s)` : `due in ${left} day(s)`));
    }
  }

  // Una seconda scansione duplicati, su tutto il registro. La prima guarda una
  // fattura contro quelle di prima; questa prende anche le coppie entrate da
  // un'altra porta — a mano, da un altro workflow, da un import.
  const fingerprint = `${key(r.supplier_name)}|${Number(r.total_amount || 0).toFixed(2)}`;
  const seen = byFingerprint.get(fingerprint);
  if (seen && key(seen.invoice_number) !== key(r.invoice_number)) {
    doubled.push(`  ${r.supplier_name} - ${amount} - ${seen.invoice_number} and ${r.invoice_number}`);
  } else if (!seen) {
    byFingerprint.set(fingerprint, r);
  }
}

const block = (title, lines) => (lines.length ? `${title} (${lines.length})\n${lines.join('\n')}\n` : '');

const report = [
  block('WAITING ON AN APPROVER', waiting),
  block('HELD, NOBODY HAS RESOLVED IT', held),
  block('DUE OR OVERDUE', dueSoon),
  block('POSSIBLE DOUBLE BILLING IN THE LEDGER', doubled),
].filter(Boolean).join('\n');

const count = waiting.length + held.length + dueSoon.length + doubled.length;

return [{
  json: {
    anything: count > 0,
    count,
    ledger_rows: rows.length,
    waiting: waiting.length,
    held: held.length,
    due_soon: dueSoon.length,
    doubled: doubled.length,
    report: report || 'Nothing open.',
  },
}];

